{"status":"edit","missing_fact":"","edits":[{"path":"logic.py","hash":"b8286e373f3208642446069714286602791f30e47f9b593c7679339a564304ec","old":"def merge_intervals(intervals):
    raise NotImplementedError("implement interval merging")
","new":"def merge_intervals(intervals):
    merged = []
    for start, end in sorted(intervals, key=lambda interval: interval[0]):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged
"}]}
